use support::*;
#[derive(Debug, PartialEq)] struct E;
struct Reader { fail: bool }
impl Reader {
 fn read(&self) -> Result<u64,E> { None }
 fn mapped(&self) -> Result<u64,E> {
  self.read().map(|v| v + 1)
 }
}
#[test] fn direct_ok() { let r = Reader { fail:false }; assert_eq!(r.mapped(), Ok(8)); }
